-- LibraryFlow catalog seed: 1,000 genuine English-language catalog entries.
-- Source: Project Gutenberg machine-readable catalog (official CSV).
-- Its Issued field is the Project Gutenberg eBook release date, so publication_year
-- below is that digital edition year, not the original print edition year.
-- ISBN is not supplied by this catalog and is left NULL. Publisher identifies the
-- digital catalog edition as Project Gutenberg.
-- Import after libraryflow.sql. Existing matching book titles and authors are skipped.
SET NAMES utf8mb4;
USE libraryflow;

CREATE TEMPORARY TABLE lf_demo_books (
  title VARCHAR(200) NOT NULL,
  author VARCHAR(150) NOT NULL,
  publisher VARCHAR(150) NOT NULL,
  category VARCHAR(80) NULL,
  publication_year SMALLINT UNSIGNED NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


SELECT NULL, seed.title, seed.author, seed.publisher, seed.category, seed.publication_year, 1
FROM lf_demo_books AS seed
LEFT JOIN books AS existing
  ON existing.title = seed.title AND existing.author = seed.author
WHERE existing.book_id IS NULL;

DROP TEMPORARY TABLE lf_demo_books;
